        my ($swaps, $target) = (0, 0);
        for 0 .. @chars.end -> $i {
            my $is_lower = @chars[$i] ~~ // ?? 1 !! 0;
            if $is_lower == $start_lower {
                $swaps  += abs($i - $target);
                $target += 2;
            }
        }
        return $swaps;
    };

    return min($calc(1), $calc(0));
}
```

